<script setup lang="ts">
import { Link, router, useForm, usePoll } from '@inertiajs/vue3';
import { ref } from 'vue';
import type { Account } from '../types';
import Errors from './Errors.vue';
import WalletNameMappings from './WalletNameMappings.vue';
type Device={created_at:string;id:number;name:string;registration_method:string;revoked_at:string|null;last_test_at:string|null;last_event_at:string|null};
type Alias={id:number;account_id:number;fingerprint:string;name_confirmed_at:string|null;identifier:{label:string;last_four?:string;network?:string}};
type Connection={id:number;name:string;enabled:boolean;devices:Device[];aliases:Alias[];last_test_at:string|null;last_event_at:string|null};
type Observation={id:number;wallet_connection_id:number;currency:string|null;payload:{merchant:string;amount_decimal:string;wallet_alias:{label:string;last_four?:string;network?:string};observed_at:string}};
const props=defineProps<{shortcut:{name:string;version:string;available:boolean;url:string|null;pairing_available:boolean;reason:string|null};connections:Connection[];accounts:Account[];unresolved:{data:Observation[];total:number;prev_page_url:string|null;next_page_url:string|null}}>();
usePoll(5000,{only:['connections','unresolved']});
const selected=ref<number|null>(props.connections.length===1 && props.connections[0].enabled?props.connections[0].id:null);const name=ref('My iPhone');const secret=ref('');const expires=ref('');const error=ref('');const busy=ref(false);const fallback=ref(false);
function csrf(){const c=document.cookie.split('; ').find(v=>v.startsWith('XSRF-TOKEN='));return c?decodeURIComponent(c.substring(11)):'';}
async function issue(importMode=false){
 secret.value='';expires.value='';error.value='';busy.value=true;fallback.value=importMode;
 try {const response=await fetch(`/integrations/wallet/${selected.value}/${importMode?'device-config':'pairings'}`,{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json','X-XSRF-TOKEN':csrf()},body:JSON.stringify({device_name:name.value})});const data=await response.json();if(!response.ok)throw new Error(data.message||'Setup request failed.');secret.value=JSON.stringify(importMode?data:{pairing_url:data.pairing_url,code:data.code},null,2);expires.value=data.expires_at||'';router.reload({only:['connections']});}catch(e){error.value=e instanceof Error?e.message:'Request failed.';}finally{busy.value=false;}
}
async function copy(){try{await navigator.clipboard.writeText(secret.value);}catch{error.value='Copy the displayed setup text manually.';}}
const resolving=ref<number|null>(null);
const assignment=useForm({account_id:null as number|null,remember:false,confirmed:false,name_unique:false});
function choose(event:Observation){resolving.value=event.id;assignment.reset();assignment.clearErrors();}
</script>
<template><section class="edit-panel wallet-card"><div class="section-heading"><div><p class="eyebrow">IPHONE SETUP</p><h2>{{ shortcut.name }}</h2><p class="small muted">Version {{ shortcut.version }} · Installation on your phone is not verified by this website.</p></div><a v-if="shortcut.available && shortcut.url" :href="shortcut.url" class="button primary" target="_blank" rel="noopener noreferrer">Install iPhone Shortcut ↗</a><button v-else class="button secondary" disabled>Install iPhone Shortcut — unavailable</button></div><p v-if="shortcut.reason" class="review-notice" role="status">{{ shortcut.reason }}</p>
<ol class="wallet-guide"><li><strong>Install:</strong> add the published shortcut to Shortcuts. Installation does not enable a Wallet automation.</li><li><strong>Pair:</strong> select your connection below, generate setup text, then paste it into the installed shortcut’s setup path. It exchanges a single-use code for a device credential.</li><li><strong>Configure automation manually:</strong> open iPhone Shortcuts → Automation → Transaction / Wallet. Select the payment cards supported by your iOS version, choose automatic execution where available, and select the installed shortcut. Grant necessary permissions. Card input and multi-card trigger behavior still require physical-device verification.</li><li><strong>Verify:</strong> run the shortcut’s manual connectivity test, then make a real purchase and check the event and account assignment. A test cannot create an expense and does not prove payment coverage.</li></ol>
<p class="small muted">A reachable HTTPS endpoint is required. Local hosting needs your Mac, server, database, and worker to stay running. localhost on the phone is not the Mac. No offline queue or automatic phone retry is implemented.</p>
<form @submit.prevent="issue(false)" class="form-grid"><label>Connection<select v-model="selected" required><option :value="null" disabled>Select a connection</option><option v-for="c in connections" :key="c.id" :value="c.id" :disabled="!c.enabled">{{ c.name }}{{ c.enabled?'':' (disabled)' }}</option></select></label><label>Device name<input v-model="name" maxlength="100" required/></label><button class="button primary" :disabled="busy || !selected || !shortcut.pairing_available">Generate pairing setup · valid 10 minutes</button></form>
<p v-if="!shortcut.pairing_available" class="review-notice">Set WALLET_PUBLIC_URL to a reachable HTTPS origin before pairing. Pairing codes cannot be exchanged over HTTP.</p><p v-if="error" role="alert" class="review-notice">{{ error }}</p>
<div v-if="secret" class="review-notice"><strong>{{ fallback?'Import configuration — device secret shown once':'Single-use pairing setup' }}</strong><p v-if="expires">Expires {{ new Date(expires).toLocaleString() }}. Paste the complete setup text into the shortcut. Never put it in a URL.</p><p v-else>This configuration contains a device token. Paste it only into your private shortcut’s import question. Do not share or export a configured shortcut.</p><pre class="wallet-code">{{ secret }}</pre><div class="wallet-actions"><button class="button secondary" @click="copy">Copy setup text</button><button class="text-button" @click="secret='';expires=''">Hide</button></div></div>
<details class="wallet-card"><summary>Import-question fallback and credential storage</summary><p>If reliable file-based pairing cannot be validated on your iPhone, a published shortcut may instead ask for one import configuration. Generate it here; no hand-written JSON or headers are needed. This explicitly bypasses code redemption and issues a separately revocable device token.</p><p>Shortcuts files and import answers are not a native Keychain implementation. Configuration may be readable in Files or the shortcut editor and may sync through iCloud. Do not share a configured shortcut. Background access while locked must be tested before the release is marked verified.</p><button class="button secondary" :disabled="busy || !selected || !shortcut.pairing_available" @click="issue(true)">Create import configuration (fallback)</button></details>
<div v-for="c in connections" :key="c.id" class="wallet-card"><h3>{{ c.name }}</h3><p class="small">Test received: {{ c.last_test_at || 'Not yet' }} · Real event received: {{ c.last_event_at || 'Not yet' }}. An unresolved event is not yet a recorded purchase.</p><p v-if="!c.devices.length" class="muted small">No device credentials issued.</p><article v-for="device in c.devices" :key="device.id" class="review-notice"><strong>{{ device.name }}</strong><p class="small">{{ device.revoked_at?'Revoked':device.registration_method==='import_question'?'Import credential issued — phone setup unverified':'Pairing code redeemed' }}<br/>Issued: {{ new Date(device.created_at).toLocaleString() }}<br/>Test: {{ device.last_test_at || 'Not received' }}<br/>Real event: {{ device.last_event_at || 'Not received' }}</p><button v-if="!device.revoked_at" class="text-button" @click="router.delete(`/integrations/wallet/${c.id}/devices/${device.id}`)">Revoke this device</button></article>
<WalletNameMappings :connection-id="c.id" :aliases="c.aliases" :accounts="accounts"/></div>
<section><h2>Identifiers needing an account · {{ unresolved.total }}</h2><p class="small muted">These observations are saved, but no expense is created until you choose an owned account. A card name can route future events after you explicitly confirm it identifies one card. Conflicting mappings require review.</p><article v-for="event in unresolved.data" :key="event.id" class="review-notice"><strong>{{ event.payload.merchant }} · {{ event.currency || 'Currency unknown' }} {{ event.payload.amount_decimal }}</strong><p>{{ event.payload.wallet_alias.label }} · {{ event.payload.wallet_alias.network || 'Network unknown' }} · {{ event.payload.wallet_alias.last_four || 'No suffix provided' }}<br/>Observed {{ event.payload.observed_at }}</p><button v-if="resolving!==event.id" class="button secondary" @click="choose(event)">Choose account</button><form v-else @submit.prevent="assignment.post(`/wallet-aliases/${event.id}/resolve`,{onSuccess:()=>resolving=null})"><Errors :errors="assignment.errors"/><label>Account<select v-model="assignment.account_id" required><option :value="null" disabled>Select your account</option><option v-for="account in accounts" :key="account.id" :value="account.id">{{ account.nickname }}</option></select></label><label class="check"><input type="checkbox" v-model="assignment.remember"/>Remember this identifier for future events</label><label v-if="assignment.remember && !event.payload.wallet_alias.last_four" class="check"><input v-model="assignment.name_unique" type="checkbox" required/>This name identifies only one card on this connection</label><label class="check"><input type="checkbox" v-model="assignment.confirmed" required/>I checked this purchase and its payment account</label><button class="button primary" :disabled="assignment.processing || !assignment.confirmed">Assign and record purchase</button></form></article><div class="wallet-actions"><Link v-if="unresolved.prev_page_url" :href="unresolved.prev_page_url">← Previous unresolved</Link><Link v-if="unresolved.next_page_url" :href="unresolved.next_page_url">Next unresolved →</Link></div></section>
</section></template>
